from pathlib import Path
import re
import subprocess
import sys

root = Path.cwd()
sys.path.insert(0, str(root / 'tools'))
from build_entering_law import take_heading

standards = [
    'FACE conduct predicates and responsibility for civil relief',
    'Commerce connection, mechanism, and class-wide effects',
    'Conditional workers’ compensation medical-payment interests',
    'Initial employment suspension and continuing procedural protection',
    'Ownership of interest generated by client trust funds',
    'ERISA employee status under general common-law agency',
    'Public-hospital evidence programs and special needs',
    'Qualified-immunity legal appeals and factual sufficiency',
    'Relevant precedent in appellate qualified-immunity review',
    'Traffic-stop completion, search consent and prior illegality',
    'Mandatory investigative procedures and substantive entitlements',
]
out = Path('terms/OT2002/entering-law/OT_2002CHUNK3_C.md')
args = [sys.executable, '-B', 'tools/build_entering_law.py', str(out)]
for title in standards:
    args += ['--standard-heading', title]
args += ['--standing-heading', '1. Current Court']
subprocess.run(args, check=True)

selections = [
    ('constitutional-structure', 'United States v. Lopez'),
    ('constitutional-structure', 'American Life League v. Reno'),
    ('constitutional-structure', 'United States v. Morrison / Brzonkala v. Morrison, 529 U.S. 598 (2000)'),
    ('first-amendment', 'American Life League v. Reno'),
    ('property-and-economic-rights', 'Phillips v. Washington Legal Foundation, 524 U.S. 156'),
    ('civil-rights', 'American Manufacturers Mutual Insurance Co. v. Sullivan'),
    ('civil-rights', 'Gilbert v. Homar'),
    ('civil-rights', 'County of Sacramento v. Lewis'),
    ('civil-rights', 'Elder v. Holloway, 510 U.S. 510'),
    ('civil-rights', 'Wilson v. Layne'),
    ('civil-rights', 'Wallis v. Spencer'),
    ('civil-rights', 'Saucier v. Katz'),
    ('civil-rights', 'Kolstad v. American Dental Association'),
    ('federal-courts-immunities-and-remedies', 'Hope v. Pelzer, 536 U.S. 730'),
    ('federal-courts-immunities-and-remedies', 'Johnson v. Jones'),
    ('federal-courts-immunities-and-remedies', 'Behrens v. Pelletier, 516 U.S. 299'),
    ('criminal-procedure-investigations', 'Ferguson v. City of Charleston, 532 U.S. 67'),
    ('criminal-procedure-investigations', 'Vernonia School District 47J v. Acton'),
    ('criminal-procedure-investigations', 'Chandler v. Miller'),
    ('criminal-procedure-investigations', 'Ohio v. Robinette'),
    ('labor-and-employment', 'Nationwide Mutual Insurance Co. v. Darden, 503 U.S. 318 (1992)'),
    ('labor-and-employment', 'Faragher v. City of Boca Raton'),
    ('labor-and-employment', 'Burlington Industries, Inc. v. Ellerth'),
    ('environmental-law', 'United States v. Bestfoods'),
]
addition = []
for volume, heading in selections:
    source = Path('state/holdings') / (volume + '.md')
    selection = take_heading(source.read_text(encoding='utf-8'), heading)
    addition += [f'## Verbatim Holdings selection: {heading}', '', f'Source: `{source.as_posix()}`.', '', selection, '']
projection = Path('terms/OT2002/workspace/neutral-projection.md').read_text(encoding='utf-8')
sections = re.split(r'(?=^### )', projection, flags=re.M)
for section in sections:
    if section.splitlines()[0].startswith('### 2002-12-10 — Planned Parenthood of the Columbia'):
        addition += ['## Effective current-term public law: Norton', '', 'Source: `terms/OT2002/workspace/neutral-projection.md`.', '', section.strip(), '']
out.write_text(out.read_text(encoding='utf-8') + '\n' + '\n'.join(addition), encoding='utf-8')

neutral = Path('terms/OT2002/runtime/OT_2002CHUNK3_NEUTRAL.md').read_text(encoding='utf-8')
parts = re.split(r'(?=^## \d+\.)', neutral, flags=re.M)
selected = [p for p in parts if re.match(r'## (36|37|39|40)\.', p)]
assert len(selected) == 4
packet = Path('terms/OT2002/freeze/OT_2002CHUNK3_C_NEUTRAL.md')
packet.write_text('# OT2002 chunk 3 — C neutral handoff\n\n'
    'The four supplied neutral entries below are copied without substantive alteration. '
    'Read the preflight addendum after those entries; its supported corrections qualify the supplied packet. '
    'The separate entering-law slice is `terms/OT2002/entering-law/OT_2002CHUNK3_C.md`.\n\n'
    + '\n'.join(selected)
    + '\n' + Path('terms/OT2002/runtime/C_PREFLIGHT_ADDENDUM.md').read_text(encoding='utf-8'), encoding='utf-8')
print('Copied four neutral entries and selected authoritative law.')
